def main() -> None:
    root = Path(__file__).resolve().parents[1] / "app" / "content"
    lessons = [l["id"] for l in json.loads((root / "lessons.json").read_text())["lessons"]]
    assert set(lessons) == set(D), set(lessons) ^ set(D)
    out = {k: {"prereqs": D[k][0], "outcomes": D[k][1], "variations": D[k][2]} for k in lessons}
    (root / "outcomes.json").write_text(json.dumps(out, indent=1, ensure_ascii=False))
    print("wrote", len(out))


if __name__ == "__main__":
    main()
